function validate([customers, grumpy, minutes]) {
  const n = customers.length;
  if (n < 1 || n > 20000) return 'customers needs 1 to 2 * 10^4 values.';
  if (grumpy.length !== n) return 'customers and grumpy must have the same length.';
  if (customers.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return 'Each customers value is between 0 and 1000.';
  if (grumpy.some(v => v !== 0 && v !== 1)) return 'Each grumpy value is 0 or 1.';
  if (!Number.isInteger(minutes) || minutes < 1 || minutes > n) return 'minutes is between 1 and n.';
  return null;
}

