function maxSatisfied(customers, grumpy, minutes) {
  let base = 0;
  for (let i = 0; i < customers.length; i++) {
    if (grumpy[i] === 0) {
      base += customers[i];
    }
  }
  let extra = 0;
  let bestExtra = 0;
  for (let i = 0; i < customers.length; i++) {
    if (grumpy[i] === 1) {
      extra += customers[i];
    }
    if (i >= minutes && grumpy[i - minutes] === 1) {
      extra -= customers[i - minutes];
    }
    bestExtra = Math.max(bestExtra, extra);
  }
  return base + bestExtra;
}

