function maxSatisfied(customers, grumpy, minutes) {
  // Try every placement of the calm block and count the happy customers from scratch.
  const n = customers.length;
  let best = 0;
  for (let start = 0; start + minutes <= n; start++) {
    let happy = 0;
    for (let i = 0; i < n; i++) {
      const calm = grumpy[i] === 0 || (i >= start && i < start + minutes);
      if (calm) happy += customers[i];
    }
    best = Math.max(best, happy);
  }
  return best;
}

