function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const cap = size === 'large' ? 1000 : (rand() < 0.5 ? 3 : 1000);
  const grumpyRate = rand();
  const customers = Array.from({ length: n }, () => Math.floor(rand() * (cap + 1)));
  const grumpy = Array.from({ length: n }, () => (rand() < grumpyRate ? 1 : 0));
  const minutes = 1 + Math.floor(rand() * n);
  return [customers, grumpy, minutes];
}
